// so a job first seen by an unrelated run still surfaces under a subscription
// that later rediscovers it (dashboard "filter by Subscription").
func (q *Queries) RecordJobRepost(ctx context.Context, arg RecordJobRepostParams) (Job, error) {
	row := q.db.QueryRow(ctx, recordJobRepost, arg.DedupeKey, arg.SubscriptionId)
	var i Job
	err := row.Scan(
		&i.ID,
		&i.DedupeKey,
		&i.SourceKey,
		&i.ExternalId,
		&i.Title,
		&i.Company,
		&i.Location,
		&i.Remote,
		&i.SalaryRaw,
		&i.Url,
		&i.Description,
		&i.Raw,
		&i.PostedAt,
		&i.IngestedAt,
		&i.Embedding,
		&i.Status,
		&i.DetailScrapedAt,
		&i.SalaryMin,
		&i.SalaryMax,
		&i.SalaryCurrency,
		&i.SalaryConfidence,
		&i.SalarySource,
		&i.SeenCount,
		&i.SubscriptionId,
		&i.SeenOnSources,
		&i.EmbeddingHash,
		&i.ExperienceLevel,
		&i.ExperienceMinYears,
		&i.EnglishLevel,
		&i.SalaryEstimateRaw,
		&i.SalaryEstimateMin,
		&i.SalaryEstimateMax,
		&i.SalaryEstimateCurrency,
		&i.LastSeenRunId,
		&i.EmbedModel,
	)
	return i, err
}

